-- US MD/MBBS (4th Year) clinical case blocks - Ophthalmology: Diabetic & hypertensive retinopathy - Part 1 (1-100)
BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'optho-retinopathy' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic optho-retinopathy not found.';
    END IF;

    -- Clear existing MCQs for this topic to avoid duplicates
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

END $$;
COMMIT;